const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,sys
from collections import Counter
from pathlib import Path
sys.path.insert(0,str(Path.cwd()))
from credentialing.evaluation import evaluate_application
work=Path('/tmp/project-e-batch1-t2qc2612')
ledger=json.loads((work/'batch1-ledger.json').read_text()); batch=ledger['batches'][0]
apps=[r for r in batch['records'] if r['filename']=='applications.csv']
outputs=[]; errors=[]
for r in apps:
 v=r['values']
 try: outputs.append(evaluate_application(ledger,v['application_id'],v['revision'],batch['export_date']))
 except Exception as e: errors.append({'application_id':v.get('application_id'),'revision':v.get('revision'),'error':type(e).__name__+': '+str(e)})
(work/'evaluations-reviewed.json').write_text(json.dumps(outputs,ensure_ascii=False,indent=2))
print(json.dumps({'unique_applications':len({x['application_id'] for x in outputs}),'revisions':len(outputs),'exceptions':errors,'states':{e:dict(Counter(x['elements'][e] for x in outputs)) for e in ('licensure','experience','gaps','education','certification','references')}},indent=2))
