from pathlib import Path
from collections import Counter
from credentialing.ingestion import empty_ledger,ingest_batch
from credentialing.readiness import process_recorded_decisions
root=Path('inputs'); sources=[root/'Batch 1 export — 2026-03-16',root/'Batch 2 export — 2026-04-20',root/'Batch 3 export — 2026-05-18']
tmp=Path(tempfile.mkdtemp(prefix='project-e-recheck-'));ledger=empty_ledger();report=[]
for src in sources:
 ing=ingest_batch(src,ledger);ledger=ing.ledger;batch=ledger['batches'][-1];asof=batch['export_date']
 pairs=[];latest={}
 for b in ledger['batches']:
  for r in b['records']:
   if r['filename']=='applications.csv':
    a,v=str(r['values']['application_id']),str(r['values']['revision'])
    if (a,v) not in pairs:pairs.append((a,v))
    latest[a]=v
 allresults={(a,v):process_recorded_decisions(ledger,a,v,asof) for a,v in pairs}
 latest_results={a:allresults[(a,v)] for a,v in latest.items()}
 decisions={}
 for x in allresults.values():
  for d in x['decision_details']:decisions[d['decision_id']]=d
 new_ids={d['decision_id'] for d in decisions.values() if d['source']['batch_id']==batch['batch_id']}
 cond_docs=[d for d in decisions.values() if d['conditions']]
 activations=[]
 for (a,v),x in allresults.items():
  act=x['schema_compatible']['activation']
  if act:activations.append({'application_id':a,'revision':v,'decision_id':x['schema_compatible']['approval_decision_id'],**act,'conditions':x['schema_compatible']['monitored_conditions']})
 report.append({'batch_id':batch['batch_id'],'as_of':asof,'new_records':len(batch['records']),'new_documents':len(batch['documents']),'issues':[i.as_dict() for i in ing.issues],
  'caseload_apps':len(latest),'revision_count':len(pairs),'latest_ready':dict(Counter('presentable' if x['readiness']['presentable'] else 'not-presentable' for x in latest_results.values())),
  'latest_status':dict(Counter(x['schema_compatible']['status'] for x in latest_results.values())),
  'all_revision_ready':dict(Counter('presentable' if x['readiness']['presentable'] else 'not-presentable' for x in allresults.values())),
  'all_revision_status':dict(Counter(x['schema_compatible']['status'] for x in allresults.values())),
  'decision_total':len(decisions),'new_decision_count':len(new_ids),'new_decisions':[{'id':d['decision_id'],'app':d['application_id'],'rev':d['revision'],'outcome':d['outcome'],'admitted':d['admitted'],'reason':d['admission_reason'],'conditions':d['conditions']} for d in decisions.values() if d['decision_id'] in new_ids],
  'cumulative_decisions':dict(Counter('admitted' if d['admitted'] else 'rejected:'+str(d['admission_reason']) for d in decisions.values())),
  'conditional_decisions':[{'id':d['decision_id'],'conditions':d['conditions'],'admitted':d['admitted']} for d in cond_docs],
  'activations':activations,
  'terminal_statuses':{a:x['schema_compatible']['status'] for a,x in latest_results.items() if x['schema_compatible']['status'] in {'withdrawn','discontinued'}}})
ledger_path=tmp/'ledger.json';ledger_path.write_text(json.dumps(ledger,ensure_ascii=False,indent=2),encoding='utf8')
summary_path=tmp/'summary.json';summary_path.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
print(json.dumps({'ledger':str(ledger_path),'summary':str(summary_path),'batches':[{k:b[k] for k in ['batch_id','as_of','new_records','new_documents','issues','caseload_apps','revision_count','latest_ready','latest_status','all_revision_ready','all_revision_status','new_decision_count','cumulative_decisions','conditional_decisions','activations','terminal_statuses']} for b in report]},ensure_ascii=False,indent=2))
