            "certification_status": "Active", "received_date": "2026-02-03", "expiry_date": "2030-12-31",
        }, 2),
        record("privilege-requests.csv", {
            "application_id": "APP-1", "revision": "1", "request_id": "REQ", "privilege_code": "PRIV-HOSP",
        }, 2)]

